-- Written by hand: the Forms app's permissions (lib/forms/rules.ts), rows like every
-- app's. Every role holds one, so anyone can be given Forms with the role they have.
INSERT INTO "rbac"."permissions" ("app", "resource", "action", "scope") VALUES
	('Forms', 'app', 'access', 'global'),
	('Forms', 'form', 'edit', 'global'),
	('Forms', 'responses', 'view_all', 'global'),
	('Forms', 'responses', 'view', 'store')
ON CONFLICT DO NOTHING;--> statement-breakpoint
